def calculate_a(N):
    a = {}
    for n in range(1, N + 1):
        if n == 1 or n == 2:
            a[n] = 1
        else:
            # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
            try:
                prev_a = a[n-1]
                term1 = a[prev_a]
                term2 = a[n - prev_a]
                a[n] = term1 + term2
            except KeyError:
                # Should not happen if calculated sequentially
                a[n] = "Error: Dependency not found"
    return a

N_max = 20
sequence = calculate_a(N_max)

# Print the results: n, a_n
print("n, a_n:")
for n in range(1, N_max + 1):
    print(f"{n}, {sequence[n]}")

